{"command":"cat <<'EOF' > direnv.go
package main

import (
	"bytes"
	"compress/zlib"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

type EnvDiff struct {
	Prev map[string]*string `json:"p"`
	Next map[string]*string `json:"n"`
}

func (d *EnvDiff) Encode() (string, error) {
	data, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	return compressAndEncode(data)
}

func DecodeDiff(s string) (*EnvDiff, error) {
	data, err := decodeAndDecompress(s)
	if err != nil {
		return nil, err
	}
	var d EnvDiff
	err = json.Unmarshal(data, &d)
	if err != nil {
		return nil, err
	}
	return &d, nil
}

func compressAndEncode(data []byte) (string, error) {
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	_, err := w.Write(data)
	if err != nil {
		return "", err
	}
	w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

func decodeAndDecompress(s string) ([]byte, error) {
	data, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		// Try without padding if it fails
		s += "="[:(4-len(s)%4)%4]
		data, err = base64.URLEncoding.DecodeString(s)
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	defer r.Close()
	return io.ReadAll(r)
}

func HashRC(path, content string) string {
	h := sha256.New()
	h.Write([]byte(path))
	h.Write([]byte("\n"))
	h.Write([]byte(content))
	return fmt.Sprintf("%x", h.Sum(nil))
}

func GetDataDir() string {
	dataHome := os.Getenv("XDG_DATA_HOME")
	if dataHome == "" {
		dataHome = filepath.Join(os.Getenv("HOME"), ".local", "share")
	}
	return filepath.Join(dataHome, "direnv")
}

func GetAllowDir() string {
	return filepath.Join(GetDataDir(), "allow")
}

func IsAllowed(path, content string) bool {
	hash := HashRC(path, content)
	allowPath := filepath.Join(GetAllowDir(), hash)
	_, err := os.Stat(allowPath)
	return err == nil
}
EOF
"}

