	fmt.Printf("disable_stdin false\n")
	fmt.Printf("warn_timeout 5s\n")
	fmt.Printf("whitelist.prefix []\n")
	fmt.Printf("whitelist.exact map[]\n")

	rcFile := os.Getenv("DIRENV_FILE")
	if rcFile != "" {
		fmt.Printf("Loaded RC path %s\n", rcFile)
		// ... more info if needed
	} else {
		fmt.Println("No .envrc or .env loaded")
	}

	dir, _ := os.Getwd()
	foundRC := findRC(dir)
	if foundRC != "" {
		fmt.Printf("Found RC path %s\n", foundRC)
		content, _ := os.ReadFile(foundRC)
		allowed := 1
		if IsAllowed(foundRC, string(content)) {
			allowed = 0
		}
		fmt.Printf("Found RC allowed %d\n", allowed)
	}
}

func reload() {
	// For reload to work, it should probably output the same as export
	// but I need the shell name.
}

func direnvExec(args []string) {
	if len(args) < 2 {
		return
	}
	dir := args[0]
	cmd := args[1]
	cmdArgs := args[2:]

	// Load environment
	absDir, _ := filepath.Abs(dir)
	rcPath := findRC(absDir)
	if rcPath != "" {
		newEnv, err := loadRC(rcPath)
		if err == nil {
			for k, v := range newEnv {
				os.Setenv(k, v)
			}
		}
	}

	binary, err := exec.LookPath(cmd)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	syscall.Exec(binary, append([]string{cmd}, cmdArgs...), os.Environ())
}

func export(args []string) {
	if len(args) == 0 {
		return
	}
	shellName := args[0]

	currentEnv := getEnv()
	diffStr := os.Getenv("DIRENV_DIFF")

	cleanEnv := make(map[string]string)
	for k, v := range currentEnv {
		cleanEnv[k] = v
	}
	if diffStr != "" {
		diff, _ := DecodeDiff(diffStr)
		if diff != nil {
			for k := range diff.Next {
				delete(cleanEnv, k)
			}
			for k, v := range diff.Prev {
				if v != nil {
					cleanEnv[k] = *v
				}
			}
		}
	}

	dir, _ := os.Getwd()
	rcPath := findRC(dir)

	var newEnv map[string]string
	if rcPath != "" {
		content, _ := os.ReadFile(rcPath)
		if !IsAllowed(rcPath, string(content)) {
			fmt.Fprintf(os.Stderr, "\033[31mdirenv: error %s is blocked. Run `direnv allow` to approve its content\033[0m\n", rcPath)
			// Still need to output something?
		} else {
			fmt.Fprintf(os.Stderr, "\033[0mdirenv: loading %s\033[0m\n", rcPath)
			env, err := loadRC(rcPath)
			if err == nil {
				newEnv = env
			}
		}
	} else if os.Getenv("DIRENV_FILE") != "" {
		fmt.Fprintf(os.Stderr, "\033[0mdirenv: unloading\033[0m\n")
	}

	if newEnv == nil {
		newEnv = cleanEnv
		// Remove direnv variables if no RC
		delete(newEnv, "DIRENV_DIR")
		delete(newEnv, "DIRENV_FILE")
		delete(newEnv, "DIRENV_WATCHES")
		delete(newEnv, "DIRENV_DIFF")
	} else {
		// Set direnv variables
		newEnv["DIRENV_DIR"] = "-" + filepath.Dir(rcPath)
		newEnv["DIRENV_FILE"] = rcPath
		// TODO: DIRENV_WATCHES
		newEnv["DIRENV_WATCHES"] = "" // placeholder
	}

	// Compute Diff
	diff := &EnvDiff{
		Prev: make(map[string]*string),
		Next: make(map[string]*string),
	}
	for k, v := range newEnv {
		if oldV, ok := cleanEnv[k]; !ok || oldV != v {
			if ok {
				val := oldV
				diff.Prev[k] = &val
			}
			val := v
			diff.Next[k] = &val
		}
	}
	for k, v := range cleanEnv {
		if _, ok := newEnv[k]; !ok {
			val := v
			diff.Prev[k] = &val
		}
	}

	newDiffStr, _ := diff.Encode()
	newEnv["DIRENV_DIFF"] = newDiffStr

	// Generate shell commands
	outputDiff(shellName, currentEnv, newEnv)
}

func outputDiff(shellName string, oldEnv, newEnv map[string]string) {
	switch shellName {
	case "bash", "zsh":
		for k, v := range newEnv {
			if oldV, ok := oldEnv[k]; !ok || oldV != v {
				fmt.Printf("export %s=%s;", k, shellQuote(v))
			}
		}
		for k := range oldEnv {
			if _, ok := newEnv[k]; !ok {
				fmt.Printf("unset %s;", k)
			}
		}
	case "fish":
		for k, v := range newEnv {
			if oldV, ok := oldEnv[k]; !ok || oldV != v {
				fmt.Printf("set -x -g %s %s;", shellQuote(k), shellQuote(v))
			}
		}
		for k := range oldEnv {
			if _, ok := newEnv[k]; !ok {
				fmt.Printf("set -e -g %s;", shellQuote(k))
			}
		}
	case "json":
		res := make(map[string]*string)
		for k, v := range newEnv {
			if oldV, ok := oldEnv[k]; !ok || oldV != v {
				val := v
				res[k] = &val
			}
		}
		for k := range oldEnv {
			if _, ok := newEnv[k]; !ok {
				res[k] = nil
			}
		}
		data, _ := json.MarshalIndent(res, "", "  ")
		fmt.Println(string(data))
	}
}

func shellQuote(s string) string {
	return "$'" + strings.ReplaceAll(s, "'", "\\'") + "'"
}

func findRC(dir string) string {
	for {
		p := filepath.Join(dir, ".envrc")
		if _, err := os.Stat(p); err == nil {
			return p
		}
		// Also check .env?
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return ""
}

func loadRC(rcPath string) (map[string]string, error) {
	self, _ := os.Executable()
	self, _ = filepath.Abs(self)

	script := fmt.Sprintf(`source <("%s" stdlib); __main__ source "%s"`, self, rcPath)
	cmd := exec.Command("bash", "-c", script)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout // This will be empty because __main__ redirects FD 1 to 2
	cmd.Stderr = &stderr

	// Create a pipe for FD 3
	r, w, _ := os.Pipe()
	cmd.ExtraFiles = []*os.File{w}

	err := cmd.Run()
	w.Close()

	if err != nil {
		fmt.Fprint(os.Stderr, stderr.String())
		return nil, err
	}

	data, _ := io.ReadAll(r)
	var env map[string]string
	err = json.Unmarshal(data, &env)
	return env, err
}

func getEnv() map[string]string {
	env := make(map[string]string)
	for _, item := range os.Environ() {
		parts := strings.SplitN(item, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

EOF
