	if len(os.Args) < 2 {
		help()
		return
	}

	cmd := os.Args[1]
	args := os.Args[2:]

	switch cmd {
	case "version":
		fmt.Println(VERSION)
	case "help":
		help()
	case "stdlib":
		stdlib()
	case "allow":
		allow(args)
	case "deny", "block", "disallow", "revoke":
		deny(args)
	case "export":
		export(args)
	case "dump":
		dump(args)
	case "hook":
		hook(args)
	case "status":
		status(args)
	case "exec":
		direnvExec(args)
	case "log":
		logCmd(args)
	case "reload":
		// skip for now
	case "prune":
		// skip for now
	default:
		fmt.Fprintf(os.Stderr, "Unknown command: %s\n", cmd)
		os.Exit(1)
	}
}

func help() {
	fmt.Printf("direnv v%s\n", VERSION)
	fmt.Println("Usage: direnv COMMAND [...ARGS]")
	fmt.Println("\nAvailable commands")
	fmt.Println("------------------")
	fmt.Println("allow [PATH_TO_RC]: Grants direnv permission to load the given .envrc or .env file.")
	fmt.Println("block [PATH_TO_RC]: Revokes the authorization of a given .envrc or .env file.")
	fmt.Println("export SHELL: Loads an .envrc or .env and prints the diff in terms of exports.")
	fmt.Println("help [SHOW_PRIVATE]: Shows this help")
	fmt.Println("hook SHELL: Used to setup the shell hook")
	fmt.Println("reload: Triggers an env reload")
	fmt.Println("status: Prints some debug status information")
	fmt.Println("stdlib: Displays the stdlib available in the .envrc execution context")
	fmt.Println("version: Prints the version")
}

func stdlib() {
	self, _ := os.Executable()
	self, _ = filepath.Abs(self)
	out := strings.ReplaceAll(STDLIB, "{{.SelfPath}}", self)
	fmt.Print(out)
}

func allow(args []string) {
	rcPath := "."
	if len(args) > 0 {
		rcPath = args[0]
	}
	absPath, _ := filepath.Abs(rcPath)
	info, err := os.Stat(absPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	if info.IsDir() {
		absPath = filepath.Join(absPath, ".envrc")
	}
	content, err := os.ReadFile(absPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	hash := HashRC(absPath, string(content))
	allowDir := GetAllowDir()
	os.MkdirAll(allowDir, 0755)
	os.WriteFile(filepath.Join(allowDir, hash), []byte(absPath), 0644)
}

func deny(args []string) {
	rcPath := "."
	if len(args) > 0 {
		rcPath = args[0]
	}
	absPath, _ := filepath.Abs(rcPath)
	info, err := os.Stat(absPath)
	if err == nil && info.IsDir() {
		absPath = filepath.Join(absPath, ".envrc")
	}
	allowDir := GetAllowDir()
	files, _ := os.ReadDir(allowDir)
	for _, f := range files {
		p := filepath.Join(allowDir, f.Name())
		content, _ := os.ReadFile(p)
		if string(content) == absPath {
			os.Remove(p)
		}
	}
}

func dump(args []string) {
	env := getEnv()
	shell := "json"
	if len(args) > 0 {
		shell = args[0]
	}

	if shell == "json" {
		data, _ := json.MarshalIndent(env, "", "  ")
		fmt.Println(string(data))
	} else {
		var keys []string
		for k := range env {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("export %s=%s;", k, shellQuote(env[k]))
		}
		fmt.Println()
	}
}

func getEnv() map[string]string {
	env := make(map[string]string)
	for _, item := range os.Environ() {
		parts := strings.SplitN(item, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

