const VERSION = "2.37.1"

type EnvDiff struct {
	Prev map[string]*string `json:"p"`
	Next map[string]*string `json:"n"`
}

func (d *EnvDiff) Encode() (string, error) {
	data, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	w.Write(data)
	w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

func DecodeDiff(s string) (*EnvDiff, error) {
	if s == "" { return nil, nil }
	s += "="[:(4-len(s)%4)%4]
	data, err := base64.URLEncoding.DecodeString(s)
	if err != nil { return nil, err }
	r, err := zlib.NewReader(bytes.NewReader(data))
	if err != nil { return nil, err }
	defer r.Close()
	dec, err := io.ReadAll(r)
	if err != nil { return nil, err }
	var d EnvDiff
	err = json.Unmarshal(dec, &d)
	return &d, err
}

func HashRC(path, content string) string {
	h := sha256.New()
	h.Write([]byte(path))
	h.Write([]byte("\n"))
	h.Write([]byte(content))
	return fmt.Sprintf("%x", h.Sum(nil))
}

func IsAllowed(path, content string) bool {
	hash := HashRC(path, content)
	dataHome := os.Getenv("XDG_DATA_HOME")
	if dataHome == "" {
		dataHome = filepath.Join(os.Getenv("HOME"), ".local", "share")
	}
	allowPath := filepath.Join(dataHome, "direnv", "allow", hash)
	_, err := os.Stat(allowPath)
	return err == nil
}

