	binary, _ := exec.LookPath(args[1])
	if binary == "" { os.Exit(1) }
	syscall.Exec(binary, args[1:], os.Environ())
}

func export(args []string) {
	shellName := "bash"
	if len(args) > 0 { shellName = args[0] }
	currentEnv := getEnv()
	diffStr := currentEnv["DIRENV_DIFF"]
	cleanEnv := make(map[string]string)
	for k, v := range currentEnv { cleanEnv[k] = v }
	if diffStr != "" {
		diff, _ := DecodeDiff(diffStr)
		if diff != nil {
			for k := range diff.Next { delete(cleanEnv, k) }
			for k, v := range diff.Prev { if v != nil { cleanEnv[k] = *v } }
		}
	}
	dir, _ := os.Getwd()
	rcPath := findRC(dir)
	var newEnv map[string]string
	if rcPath != "" {
		content, _ := os.ReadFile(rcPath)
		if IsAllowed(rcPath, string(content)) {
			fmt.Fprintf(os.Stderr, "direnv: loading %s\n", rcPath)
			newEnv, _ = loadRC(rcPath)
		} else {
			fmt.Fprintf(os.Stderr, "direnv: %s is blocked\n", rcPath)
		}
	} else if currentEnv["DIRENV_FILE"] != "" {
		fmt.Fprintf(os.Stderr, "direnv: unloading\n")
	}
	if newEnv == nil {
		newEnv = cleanEnv
		delete(newEnv, "DIRENV_DIR"); delete(newEnv, "DIRENV_FILE")
		delete(newEnv, "DIRENV_DIFF"); delete(newEnv, "DIRENV_WATCHES")
	} else {
		newEnv["DIRENV_DIR"] = "-" + filepath.Dir(rcPath)
		newEnv["DIRENV_FILE"] = rcPath
		newEnv["DIRENV_WATCHES"] = ""
	}
	diff := &EnvDiff{Prev: make(map[string]*string), Next: make(map[string]*string)}
	for k, v := range newEnv {
		if oldV, ok := cleanEnv[k]; !ok || oldV != v {
			if ok { val := oldV; diff.Prev[k] = &val }
			val := v; diff.Next[k] = &val
		}
	}
	for k, v := range cleanEnv {
		if _, ok := newEnv[k]; !ok { val := v; diff.Prev[k] = &val }
	}
	newDiffStr, _ := diff.Encode()
	newEnv["DIRENV_DIFF"] = newDiffStr
	outputDiff(shellName, currentEnv, newEnv)
}

func outputDiff(shellName string, oldEnv, newEnv map[string]string) {
	if shellName == "json" {
		res := make(map[string]*string)
		for k, v := range newEnv {
			if oldV, ok := oldEnv[k]; !ok || oldV != v { val := v; res[k] = &val }
		}
		for k := range oldEnv {
			if _, ok := newEnv[k]; !ok { res[k] = nil }
		}
		data, _ := json.MarshalIndent(res, "", "  ")
		fmt.Println(string(data))
		return
	}
	for k, v := range newEnv {
		if oldV, ok := oldEnv[k]; !ok || oldV != v {
			if shellName == "fish" { fmt.Printf("set -gx %s %s;", k, shellQuote(v)) } else { fmt.Printf("export %s=%s;", k, shellQuote(v)) }
		}
	}
	for k := range oldEnv {
		if _, ok := newEnv[k]; !ok {
			if shellName == "fish" { fmt.Printf("set -e %s;", k) } else { fmt.Printf("unset %s;", k) }
		}
	}
}

func shellQuote(s string) string {
	if s == "" { return "''" }
	if strings.ContainsAny(s, "\n\t\r") {
		r := strings.NewReplacer("\n", "\\n", "\r", "\\r", "\t", "\\t", "'", "\\'")
		return "$'" + r.Replace(s) + "'"
	}
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}
